const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define locations
  const dallasport = ee.Geometry.Point([-121.1661, 45.6173]);
  const medford = ee.Geometry.Point([-122.8758, 42.3265]);

  // Use MODIS LST data (2000-present) to check historical maximums
  const startDate = '2000-01-01';
  const endDate = '2024-12-31';

  // Get MODIS LST day data
  let lstCollection = ee.ImageCollection('MODIS/061/MOD11A1')
    .select('LST_Day_1km')
    .filterDate(startDate, endDate);

  const collectionSize = await lstCollection.size().getInfo();
  console.log('Total MODIS images:', collectionSize);

  if (collectionSize === 0) {
    console.log('No data found.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Convert Kelvin to Fahrenheit: (K - 273.15) * 9/5 + 32
  // MODIS LST is in Kelvin * 50, so divide by 50 first
  const convertToFahrenheit = function(image) {
    const kelvin = image.multiply(0.02);
    const fahrenheit = kelvin.subtract(273.15).multiply(9/5).add(32);
    return fahrenheit.copyProperties(image, ['system:time_start']);
  };

  const lstFahrenheit = lstCollection.map(convertToFahrenheit);

  // Get maximum temperature for each location
  const maxLst = lstFahrenheit.max();

  // Check Dallasport
  const dallasportStats = await maxLst.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: dallasport,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const dallasportMax = dallasportStats.LST_Day_1km;

  // Check Medford
  const medfordStats = await maxLst.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: medford,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const medfordMax = medfordStats.LST_Day_1km;

  console.log('Dallasport max temp:', dallasportMax ? dallasportMax.toFixed(2) + '°F' : 'null');
  console.log('Medford max temp:', medfordMax ? medfordMax.toFixed(2) + '°F' : 'null');

  // Validate results
  if (dallasportMax === null || medfordMax === null || 
      isNaN(dallasportMax) || isNaN(medfordMax)) {
    console.log('Calculation failed - null or NaN result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check for unrealistic temperatures
  if (dallasportMax > 150 || dallasportMax < -50 || 
      medfordMax > 150 || medfordMax < -50) {
    console.log('Unrealistic temperature values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if either location exceeded 105°F
  const threshold = 105.0;
  console.log('Threshold: 105°F');

  if (dallasportMax > threshold || medfordMax > threshold) {
    console.log('At least one location exceeded 105°F');
    console.log('<answer>A</answer>');
  } else {
    console.log('Neither location exceeded 105°F');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
